<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {number,price,time} from '../format'
import {quantLabel} from '../quant'
import {studyLabel} from '../quantStudy'
import type {StudyStatus,StudySummary,StudyTrade} from '../quantStudy'
import PageIntro from '../components/PageIntro.vue'
import QuantDiagnostics from '../components/QuantDiagnostics.vue'

const data=ref<StudyStatus|null>(null);const busy=ref(false);const actionError=ref('');const window=ref('Holdout');const cost=ref('1');const trades=ref<StudyTrade[]>([]);const selected=ref<StudySummary|null>(null);const detailBusy=ref(false)
async function load(signal?:AbortSignal){data.value=await api<StudyStatus>('/api/quant/validation',{signal})}
const {error}=usePolling(load,10000)
const report=computed(()=>data.value?.report)
const summaries=computed(()=>report.value?.summaries.filter(s=>s.window===window.value&&s.costMultiplier===Number(cost.value))??[])
const progress=computed(()=>data.value?.progress)
const diagnosticRow=ref<StudySummary|null>(null)
let detailGeneration=0
watch([window,cost,()=>report.value?.request.id],()=>{detailGeneration++;selected.value=null;trades.value=[];detailBusy.value=false;diagnosticRow.value=null})
async function start(){if(busy.value||data.value?.running)return;busy.value=true;actionError.value='';try{await post('/api/quant/validation/run');await load()}catch(e){actionError.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function detail(row:StudySummary){if(!report.value)return;const generation=++detailGeneration;selected.value=row;trades.value=[];detailBusy.value=true;actionError.value='';try{const value=await api<StudyTrade[]>(`/api/quant/validation/trades?id=${encodeURIComponent(report.value.request.id)}&window=${row.window}&strategy=${row.strategy}&policy=${row.policy}&cost=${row.costMultiplier}&limit=25`);if(generation===detailGeneration)trades.value=value}catch(e){if(generation===detailGeneration)actionError.value=e instanceof Error?e.message:String(e)}finally{if(generation===detailGeneration)detailBusy.value=false}}
</script>
<template><PageIntro eyebrow="QUANT VALIDATION · FIXED RULES" title="固定规则的回放与验证" description="历史价格情景、完整证据核对与真正的前瞻记录分别展示。这里的独立机会样本不能相加成账户收益。"><RouterLink to="/">返回工作台 →</RouterLink></PageIntro>
<section class="detail"><div class="study-heading"><div><h2>60天固定历史研究</h2><p>开发30天、验证15天、历史留出15天；各段最后72小时不接纳新研究入场。比较两种退出和三档成本，不搜索参数。</p></div><button class="replay-action" :disabled="busy||data?.running" @click="start">{{busy?'提交中':data?.running?'后台研究进行中':'生成新的固定回放'}}</button></div><p class="radar-notice">100U名义价值、无杠杆、连续数量的价格情景研究。历史OI、盘口、保证金档位与完整资金费缺覆盖，不等于原模拟账户表现或实盘收益。</p><p class="muted">生成任务会冻结当前候选名单；本地不足的历史经原限流/计量接口一次补齐，每币最多两页。沿用30GB月度预算，查看页面只读已有结果。</p>
<p v-if="error||actionError||data?.error" class="radar-notice" role="alert">{{actionError||data?.error||error}}</p>
<p v-if="progress">{{studyLabel(progress.status)}} · {{progress.message}} · 已收集 {{progress.collected}} / {{progress.request.universe.length}}，已回放 {{progress.processed}} / {{progress.request.universe.length}}。更新 {{time(progress.updatedAt)}}。</p><p v-if="!report">尚无完成的报告，零样本不视为通过。</p><p v-if="report&&progress&&report.request.id!==progress.request.id" class="radar-notice">下方仍是上一份完成报告，新任务尚未完成。</p></section>

<template v-if="report"><section class="detail"><h2>研究边界与证据状态</h2><p>历史范围 {{time(report.request.from)}} → {{time(report.request.through)}}；{{report.sources.length}}个合约；完成 {{time(report.completedAt)}}。当前名单回看包含幸存者和选样偏差。</p><div class="study-gates"><div v-for="g in report.gates" :key="g.name"><strong>{{studyLabel(g.name)}} · {{studyLabel(g.status)}}</strong><p>{{g.detail}}</p></div></div><p>前瞻原始记录重算：{{report.forward.matches}} / {{report.forward.decisions}}条一致；不一致 {{report.forward.mismatches}}、缺输入 {{report.forward.missingInputs}}。{{report.forward.decisions===0?'尚无可校对记录。':'重算一致只说明工程可复现。'}}</p><p v-for="i in report.forward.issues" :key="i" class="radar-notice">{{i}}</p></section>
<section class="detail"><h2>退出与成本对照</h2><div class="study-filters"><label>时间段<select v-model="window" aria-label="回放时间段"><option value="Development">开发段</option><option value="Validation">验证段</option><option value="Holdout">历史留出段</option></select></label><label>成本压力<select v-model="cost" aria-label="回放成本压力"><option value="1">1倍假设成本</option><option value="2">2倍压力</option><option value="3">3倍压力</option></select></label></div>
<p class="muted">模型净R：初始价格止损风险为1R，费用或跳空可使损失超过1R。手续费/滑点各每边0.05%，资金费每小时0.01%均按不利方向假设。均值区间按UTC信号日期整组重采样，资料不足显示Unknown。</p><div class="table-wrap"><table><thead><tr><th>策略 / 退出</th><th>完成 / 样本</th><th>缺路径</th><th>歧义</th><th>止损优先均值R</th><th>目标优先均值R</th><th>利润因子</th><th>模型胜率</th><th>多 / 空</th><th>日期组 / 均值95%区间</th><th>证据</th></tr></thead><tbody><tr v-for="s in summaries" :key="s.strategy+s.policy"><td>{{quantLabel(s.strategy)}}<small>{{studyLabel(s.policy)}}</small></td><td>{{s.completed}} / {{s.trades}}</td><td>{{s.missingPath}}</td><td>{{s.ambiguous}}</td><td>{{number(s.meanNetR,3)}}</td><td>{{number(s.targetFirstMeanNetR,3)}}</td><td>{{number(s.profitFactor,3)}}</td><td>{{number(s.winRate,1)}}%</td><td>{{s.longTrades}} / {{s.shortTrades}}</td><td>{{s.signalDays}}组<small>{{number(s.meanLower95,3)}} ～ {{number(s.meanUpper95,3)}}</small></td><td><button class="text-button" @click="detail(s)">逐笔路径</button><button class="text-button" @click="diagnosticRow=s">亏损分解</button></td></tr></tbody></table></div><p class="muted">利润因子无亏损分母或零样本时保持Unknown；不同变体不是独立新交易，不相加。</p></section>
<QuantDiagnostics v-if="diagnosticRow" :id="report.request.id" :window="diagnosticRow.window" :strategy="diagnosticRow.strategy" :policy="diagnosticRow.policy" :cost="diagnosticRow.costMultiplier" />
<section v-if="selected" class="detail"><h2>{{studyLabel(selected.window)}} · {{quantLabel(selected.strategy)}} · {{studyLabel(selected.policy)}} · {{selected.costMultiplier}}倍成本</h2><p v-if="detailBusy">读取本地路径记录中。</p><p v-else-if="!trades.length">该变体没有研究入场，不能据此证明有效。</p><details v-for="t in trades" :key="t.id" class="study-trade"><summary>{{t.symbol}} · {{quantLabel(t.direction)}} · {{time(t.signalHour)}} · {{studyLabel(t.conservative.status)}} · 模型净R {{number(t.conservative.net==null?null:t.conservative.net/t.conservative.initialRisk,3)}}</summary><p>假设入场 {{price(t.seed.entry)}}，数量 {{price(t.seed.quantity)}}；结构失效 {{price(t.seed.stop)}}，目标 {{price(t.seed.target1)}} / {{price(t.seed.target2)}}。重建时间 {{time(t.reconstructedAt)}}，不是历史真实收到信号的时间。</p><p>止损优先净额 {{number(t.conservative.net,4)}} U；目标优先净额 {{number(t.targetFirst.net,4)}} U。费用 {{number(t.conservative.fees,4)}} U，资金费压力 {{number(t.conservative.funding,4)}} U。{{t.conservative.reason}}</p><p v-for="(l,i) in t.conservative.legs" :key="i">{{time(l.at)}} · {{studyLabel(l.reason)}} · 价格 {{price(l.price)}} · 数量 {{price(l.quantity)}}。对应小时起点 {{time(l.barOpen)}}。</p><small class="muted">源摘要 {{t.sourceHash}}</small></details></section>
<section class="detail"><details><summary>数据覆盖、缺口与参数</summary><div class="table-wrap"><table><thead><tr><th>合约</th><th>小时数</th><th>起止</th><th>来源 / 缺失</th><th>摘要</th></tr></thead><tbody><tr v-for="s in report.sources" :key="s.symbol"><td>{{s.symbol}}</td><td>{{s.candles}}</td><td>{{time(s.first)}}<small>{{time(s.through)}}</small></td><td>{{s.source}}<small>{{s.error}}</small></td><td>{{s.hash.slice(0,12)}}</td></tr></tbody></table></div><p v-for="(v,k) in report.counts" :key="k">{{k}}：{{v}}</p><p v-for="w in report.request.windows" :key="w.name">{{studyLabel(w.name)}}：{{time(w.from)}} → {{time(w.through)}}；新入场必须早于 {{time(w.lastEntryExclusive)}}。</p><p class="muted">策略SHA256 {{report.request.rulesHash}}；研究SHA256 {{report.request.studyHash}}；报告 {{report.request.id}}。</p></details><h3>结论适用范围</h3><p v-for="n in report.limitations" :key="n" class="muted">{{n}}</p></section></template></template>
<style scoped>
.table-wrap{max-width:100%;overflow-x:auto}.table-wrap .text-button{display:block;margin:4px 0;white-space:nowrap}

.study-heading{display:flex;justify-content:space-between;gap:22px;align-items:center;flex-wrap:wrap}.study-gates{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:20px 0}.study-gates>div{padding:16px;border:1px solid #30444e;border-radius:8px;background:#101b22}.study-gates p{font-size:13px;color:#9bb2c2}.study-filters{display:flex;gap:20px;margin:16px 0;flex-wrap:wrap}.study-filters label{display:grid;gap:7px}.study-filters select{background:#101820;color:inherit;border:1px solid #3b4c59;padding:9px;border-radius:4px}.study-trade{padding:14px 0;border-bottom:1px solid #293b46}.study-trade summary{cursor:pointer;line-height:1.8}.muted{overflow-wrap:anywhere}@media(max-width:800px){.study-gates{grid-template-columns:1fr}}
</style>
